insert into public.legal_provisions (
    version_id, provision_key, sequence, heading_path, heading, label, content
)
select
    '21000000-0000-4000-8000-000000000010', item.chave, item.sequencia, item.caminho, item.titulo, item.rotulo, item.conteudo
from jsonb_to_recordset($dados$[{"chave":"art-1","sequencia":1,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO I — DO SISTEMA NACIONAL DE ARMAS"],"titulo":"CAPÍTULO I — DO SISTEMA NACIONAL DE ARMAS","rotulo":"Art. 1º","conteudo":"O Sistema Nacional de Armas – Sinarm, instituído no Ministério da Justiça, no âmbito da Polícia Federal, tem circunscrição em todo o território nacional."},{"chave":"art-2","sequencia":2,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO I — DO SISTEMA NACIONAL DE ARMAS"],"titulo":"CAPÍTULO I — DO SISTEMA NACIONAL DE ARMAS","rotulo":"Art. 2º","conteudo":"Ao Sinarm compete:\n\nI – identificar as características e a propriedade de armas de fogo, mediante cadastro;\n\nII – cadastrar as armas de fogo produzidas, importadas e vendidas no País;\n\nIII – cadastrar as autorizações de porte de arma de fogo e as renovações expedidas pela Polícia Federal;\n\nIV – cadastrar as transferências de propriedade, extravio, furto, roubo e outras ocorrências suscetíveis de alterar os dados cadastrais, inclusive as decorrentes de fechamento de empresas de segurança privada e de transporte de valores;\n\nV – identificar as modificações que alterem as características ou o funcionamento de arma de fogo;\n\nVI – integrar no cadastro os acervos policiais já existentes;\n\nVII – cadastrar as apreensões de armas de fogo, inclusive as vinculadas a procedimentos policiais e judiciais;\n\nVIII – cadastrar os armeiros em atividade no País, bem como conceder licença para exercer a atividade;\n\nIX – cadastrar mediante registro os produtores, atacadistas, varejistas, exportadores e importadores autorizados de armas de fogo, acessórios e munições;\n\nX – cadastrar a identificação do cano da arma, as características das impressões de raiamento e de microestriamento de projétil disparado, conforme marcação e testes obrigatoriamente realizados pelo fabricante;\n\nXI – informar às Secretarias de Segurança Pública dos Estados e do Distrito Federal os registros e autorizações de porte de armas de fogo nos respectivos territórios, bem como manter o cadastro atualizado para consulta.\n\nParágrafo único. As disposições deste artigo não alcançam as armas de fogo das Forças Armadas e Auxiliares, bem como as demais que constem dos seus registros próprios."},{"chave":"art-3","sequencia":3,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO II — DO REGISTRO"],"titulo":"CAPÍTULO II — DO REGISTRO","rotulo":"Art. 3º","conteudo":"É obrigatório o registro de arma de fogo no órgão competente.\n\nParágrafo único. As armas de fogo de uso restrito serão registradas no Comando do Exército, na forma do regulamento desta Lei."},{"chave":"art-4","sequencia":4,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO II — DO REGISTRO"],"titulo":"CAPÍTULO II — DO REGISTRO","rotulo":"Art. 4º","conteudo":"Para adquirir arma de fogo de uso permitido o interessado deverá, além de declarar a efetiva necessidade, atender aos seguintes requisitos:\n\nI - comprovação de idoneidade, com a apresentação de certidões negativas de antecedentes criminais fornecidas pela Justiça Federal, Estadual, Militar e Eleitoral e de não estar respondendo a inquérito policial ou a processo criminal, que poderão ser fornecidas por meios eletrônicos; (Redação dada pela Lei nº 11.706, de 2008)\n\nII – apresentação de documento comprobatório de ocupação lícita e de residência certa;\n\nIII – comprovação de capacidade técnica e de aptidão psicológica para o manuseio de arma de fogo, atestadas na forma disposta no regulamento desta Lei.\n\n§ 1º O Sinarm expedirá autorização de compra de arma de fogo após atendidos os requisitos anteriormente estabelecidos, em nome do requerente e para a arma indicada, sendo intransferível esta autorização.\n\n§ 2º A aquisição de munição somente poderá ser feita no calibre correspondente à arma registrada e na quantidade estabelecida no regulamento desta Lei. (Redação dada pela Lei nº 11.706, de 2008) (Vide ADI 6466) (Vide ADI 6139)\n\n§ 3º A empresa que comercializar arma de fogo em território nacional é obrigada a comunicar a venda à autoridade competente, como também a manter banco de dados com todas as características da arma e cópia dos documentos previstos neste artigo.\n\n§ 4º A empresa que comercializa armas de fogo, acessórios e munições responde legalmente por essas mercadorias, ficando registradas como de sua propriedade enquanto não forem vendidas.\n\n§ 5º A comercialização de armas de fogo, acessórios e munições entre pessoas físicas somente será efetivada mediante autorização do Sinarm.\n\n§ 6º A expedição da autorização a que se refere o § 1º será concedida, ou recusada com a devida fundamentação, no prazo de 30 (trinta) dias úteis, a contar da data do requerimento do interessado.\n\n§ 7º O registro precário a que se refere o § 4º prescinde do cumprimento dos requisitos dos incisos I, II e III deste artigo.\n\n§ 8º Estará dispensado das exigências constantes do inciso III do caput deste artigo, na forma do regulamento, o interessado em adquirir arma de fogo de uso permitido que comprove estar autorizado a portar arma com as mesmas características daquela a ser adquirida. (Incluído pela Lei nº 11.706, de 2008)"},{"chave":"art-5","sequencia":5,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO II — DO REGISTRO"],"titulo":"CAPÍTULO II — DO REGISTRO","rotulo":"Art. 5º","conteudo":"O certificado de Registro de Arma de Fogo, com validade em todo o território nacional, autoriza o seu proprietário a manter a arma de fogo exclusivamente no interior de sua residência ou domicílio, ou dependência desses, ou, ainda, no seu local de trabalho, desde que seja ele o titular ou o responsável legal pelo estabelecimento ou empresa. (Redação dada pela Lei nº 10.884, de 2004)\n\n§ 1º O certificado de registro de arma de fogo será expedido pela Polícia Federal e será precedido de autorização do Sinarm.\n\n§ 2º Os requisitos de que tratam os incisos I, II e III do art. 4º deverão ser comprovados periodicamente, em período não inferior a 3 (três) anos, na conformidade do estabelecido no regulamento desta Lei, para a renovação do Certificado de Registro de Arma de Fogo.\n\n§ 3º O proprietário de arma de fogo com certificados de registro de propriedade expedido por órgão estadual ou do Distrito Federal até a data da publicação desta Lei que não optar pela entrega espontânea prevista no art. 32 desta Lei deverá renová-lo mediante o pertinente registro federal, até o dia 31 de dezembro de 2008, ante a apresentação de documento de identificação pessoal e comprovante de residência fixa, ficando dispensado do pagamento de taxas e do cumprimento das demais exigências constantes dos incisos I a III do caput do art. 4º desta Lei. (Redação dada pela Lei nº 11.706, de 2008) (Prorrogação de prazo)\n\n§ 4º Para fins do cumprimento do disposto no § 3º deste artigo, o proprietário de arma de fogo poderá obter, no Departamento de Polícia Federal, certificado de registro provisório, expedido na rede mundial de computadores - internet, na forma do regulamento e obedecidos os procedimentos a seguir: (Redação dada pela Lei nº 11.706, de 2008)\n\nI - emissão de certificado de registro provisório pela internet, com validade inicial de 90 (noventa) dias; e (Incluído pela Lei nº 11.706, de 2008)\n\nII - revalidação pela unidade do Departamento de Polícia Federal do certificado de registro provisório pelo prazo que estimar como necessário para a emissão definitiva do certificado de registro de propriedade. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 5º Aos residentes em área rural, para os fins do disposto no caput deste artigo, considera-se residência ou domicílio toda a extensão do respectivo imóvel rural. (Incluído pela Lei nº 13.870, de 2019)"},{"chave":"art-6","sequencia":6,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 6º","conteudo":"É proibido o porte de arma de fogo em todo o território nacional, salvo para os casos previstos em legislação própria e para:\n\nI – os integrantes das Forças Armadas;\n\nII - os integrantes de órgãos referidos nos incisos I, II, III, IV e V do caput do art. 144 da Constituição Federal e os da Força Nacional de Segurança Pública (FNSP); (Redação dada pela Lei nº 13.500, de 2017)\n\nIII – os integrantes das guardas municipais e dos Municípios, nas condições estabelecidas no regulamento desta Lei; (Expressões declaradas inconstitucionais pela ADIN 5538) (Vide ADIN 5948) (Vide ADC 38) (Vide expressões declaradas inconstitucionais)\n\nIV - (Declarado inconstitucional pela ADIN 5538) (Vide ADIN 5948) (Vide ADC 38) (Vide expressões declaradas inconstitucionais)\n\nV – os agentes operacionais da Agência Brasileira de Inteligência e os agentes do Departamento de Segurança do Gabinete de Segurança Institucional da Presidência da República; (Vide Decreto nº 9.685, de 2019)\n\nVI – os integrantes das polícias legislativas referidas no art. 27, § 3º, no art. 51, inciso IV, e no art. 52, inciso XIII, da Constituição Federal; (Redação dada pela Lei nº 15.306, de 2025)\n\nVII – os integrantes do quadro efetivo dos agentes e guardas prisionais, os integrantes das escoltas de presos e as guardas portuárias;\n\nVIII – as empresas de segurança privada e de transporte de valores constituídas, nos termos desta Lei;\n\nIX – para os integrantes das entidades de desporto legalmente constituídas, cujas atividades esportivas demandem o uso de armas de fogo, na forma do regulamento desta Lei, observando-se, no que couber, a legislação ambiental.\n\nX - integrantes das Carreiras de Auditoria da Receita Federal do Brasil e de Auditoria-Fiscal do Trabalho, cargos de Auditor-Fiscal e Analista Tributário. (Redação dada pela Lei nº 11.501, de 2007)\n\nXI - os tribunais do Poder Judiciário descritos no art. 92 da Constituição Federal e os Ministérios Públicos da União e dos Estados, para uso exclusivo de servidores de seus quadros pessoais que efetivamente estejam no exercício de funções de segurança, na forma de regulamento a ser emitido pelo Conselho Nacional de Justiça - CNJ e pelo Conselho Nacional do Ministério Público - CNMP. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 1º As pessoas previstas nos incisos I, II, III, V e VI do caput deste artigo terão direito de portar arma de fogo de propriedade particular ou fornecida pela respectiva corporação ou instituição, mesmo fora de serviço, nos termos do regulamento desta Lei, com validade em âmbito nacional para aquelas constantes dos incisos I, II, V e VI. (Redação dada pela Lei nº 11.706, de 2008)\n\n§ 1º-A (Revogado pela Lei nº 11.706, de 2008)\n\n§ 1º-B. Os integrantes do quadro efetivo de agentes e guardas prisionais poderão portar arma de fogo de propriedade particular ou fornecida pela respectiva corporação ou instituição, mesmo fora de serviço, desde que estejam: (Incluído pela Lei nº 12.993, de 2014)\n\nI - submetidos a regime de dedicação exclusiva; (Incluído pela Lei nº 12.993, de 2014)\n\nII - sujeitos à formação funcional, nos termos do regulamento; e (Incluído pela Lei nº 12.993, de 2014)\n\nIII - subordinados a mecanismos de fiscalização e de controle interno. (Incluído pela Lei nº 12.993, de 2014)\n\n§ 1º-C. (VETADO). (Incluído pela Lei nº 12.993, de 2014)\n\n§ 2º A autorização para o porte de arma de fogo aos integrantes das instituições descritas nos incisos V, VI, VII e X do caput deste artigo está condicionada à comprovação do requisito a que se refere o inciso III do caput do art. 4º desta Lei nas condições estabelecidas no regulamento desta Lei. (Redação dada pela Lei nº 11.706, de 2008)\n\n§ 3º A autorização para o porte de arma de fogo das guardas municipais está condicionada à formação funcional de seus integrantes em estabelecimentos de ensino de atividade policial, à existência de mecanismos de fiscalização e de controle interno, nas condições estabelecidas no regulamento desta Lei, observada a supervisão do Ministério da Justiça. (Redação dada pela Lei nº 10.884, de 2004)\n\n§ 4º Os integrantes das Forças Armadas, das polícias federais e estaduais e do Distrito Federal, bem como os militares dos Estados e do Distrito Federal, ao exercerem o direito descrito no art. 4º, ficam dispensados do cumprimento do disposto nos incisos I, II e III do mesmo artigo, na forma do regulamento desta Lei.\n\n§ 5º Aos residentes em áreas rurais, maiores de 25 (vinte e cinco) anos que comprovem depender do emprego de arma de fogo para prover sua subsistência alimentar familiar será concedido pela Polícia Federal o porte de arma de fogo, na categoria caçador para subsistência, de uma arma de uso permitido, de tiro simples, com 1 (um) ou 2 (dois) canos, de alma lisa e de calibre igual ou inferior a 16 (dezesseis), desde que o interessado comprove a efetiva necessidade em requerimento ao qual deverão ser anexados os seguintes documentos: (Redação dada pela Lei nº 11.706, de 2008)\n\nI - documento de identificação pessoal; (Incluído pela Lei nº 11.706, de 2008)\n\nII - comprovante de residência em área rural; e (Incluído pela Lei nº 11.706, de 2008)\n\nIII - atestado de bons antecedentes. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 6º O caçador para subsistência que der outro uso à sua arma de fogo, independentemente de outras tipificações penais, responderá, conforme o caso, por porte ilegal ou por disparo de arma de fogo de uso permitido. (Redação dada pela Lei nº 11.706, de 2008)\n\n§ 7º Aos integrantes das guardas municipais dos Municípios que integram regiões metropolitanas será autorizado porte de arma de fogo, quando em serviço. (Incluído pela Lei nº 11.706, de 2008)"},{"chave":"art-7","sequencia":7,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 7º","conteudo":"As armas de fogo utilizadas pelos profissionais de segurança privada dos prestadores de serviços de segurança privada e das empresas e dos condomínios edilícios possuidores de serviços orgânicos de segurança privada, constituídas na forma da lei, serão de propriedade, responsabilidade e guarda das respectivas empresas, somente podendo ser utilizadas quando em serviço, devendo essas observarem as condições de uso e de armazenagem estabelecidas pelo órgão competente, sendo o certificado de registro e a autorização de porte expedidos pela Polícia Federal em nome da empresa. (Redação dada pela Lei nº 14.967, de 2024)\n\n§ 1º O proprietário ou diretor responsável de empresa de segurança privada e de transporte de valores responderá pelo crime previsto no parágrafo único do art. 13 desta Lei, sem prejuízo das demais sanções administrativas e civis, se deixar de registrar ocorrência policial e de comunicar à Polícia Federal perda, furto, roubo ou outras formas de extravio de armas de fogo, acessórios e munições que estejam sob sua guarda, nas primeiras 24 (vinte e quatro) horas depois de ocorrido o fato.\n\n§ 2º A empresa de segurança e de transporte de valores deverá apresentar documentação comprobatória do preenchimento dos requisitos constantes do art. 4º desta Lei quanto aos empregados que portarão arma de fogo.\n\n§ 3º A listagem dos empregados das empresas referidas neste artigo deverá ser atualizada semestralmente junto ao Sinarm."},{"chave":"art-7-a","sequencia":8,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 7º-A","conteudo":"As armas de fogo utilizadas pelos servidores das instituições descritas no inciso XI do art. 6º serão de propriedade, responsabilidade e guarda das respectivas instituições, somente podendo ser utilizadas quando em serviço, devendo estas observar as condições de uso e de armazenagem estabelecidas pelo órgão competente, sendo o certificado de registro e a autorização de porte expedidos pela Polícia Federal em nome da instituição. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 1º A autorização para o porte de arma de fogo de que trata este artigo independe do pagamento de taxa. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 2º O presidente do tribunal ou o chefe do Ministério Público designará os servidores de seus quadros pessoais no exercício de funções de segurança que poderão portar arma de fogo, respeitado o limite máximo de 50% (cinquenta por cento) do número de servidores que exerçam funções de segurança. (Incluído pela Lei nº 12.694, de 2012) (Vide ADI 5157)\n\n§ 3º O porte de arma pelos servidores das instituições de que trata este artigo fica condicionado à apresentação de documentação comprobatória do preenchimento dos requisitos constantes do art. 4º desta Lei, bem como à formação funcional em estabelecimentos de ensino de atividade policial e à existência de mecanismos de fiscalização e de controle interno, nas condições estabelecidas no regulamento desta Lei. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 4º A listagem dos servidores das instituições de que trata este artigo deverá ser atualizada semestralmente no Sinarm. (Incluído pela Lei nº 12.694, de 2012)\n\n§ 5º As instituições de que trata este artigo são obrigadas a registrar ocorrência policial e a comunicar à Polícia Federal eventual perda, furto, roubo ou outras formas de extravio de armas de fogo, acessórios e munições que estejam sob sua guarda, nas primeiras 24 (vinte e quatro) horas depois de ocorrido o fato. (Incluído pela Lei nº 12.694, de 2012)"},{"chave":"art-8","sequencia":9,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 8º","conteudo":"As armas de fogo utilizadas em entidades desportivas legalmente constituídas devem obedecer às condições de uso e de armazenagem estabelecidas pelo órgão competente, respondendo o possuidor ou o autorizado a portar a arma pela sua guarda na forma do regulamento desta Lei."},{"chave":"art-9","sequencia":10,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 9º","conteudo":"Compete ao Ministério da Justiça a autorização do porte de arma para os responsáveis pela segurança de cidadãos estrangeiros em visita ou sediados no Brasil e, ao Comando do Exército, nos termos do regulamento desta Lei, o registro e a concessão de porte de trânsito de arma de fogo para colecionadores, atiradores e caçadores e de representantes estrangeiros em competição internacional oficial de tiro realizada no território nacional."},{"chave":"art-10","sequencia":11,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 10.","conteudo":"A autorização para o porte de arma de fogo de uso permitido, em todo o território nacional, é de competência da Polícia Federal e somente será concedida após autorização do Sinarm.\n\n§ 1º A autorização prevista neste artigo poderá ser concedida com eficácia temporária e territorial limitada, nos termos de atos regulamentares, e dependerá de o requerente:\n\nI – demonstrar a sua efetiva necessidade por exercício de atividade profissional de risco ou de ameaça à sua integridade física; (Vide ADI 6139)\n\nII – atender às exigências previstas no art. 4º desta Lei;\n\nIII – apresentar documentação de propriedade de arma de fogo, bem como o seu devido registro no órgão competente.\n\n§ 2º A autorização de porte de arma de fogo, prevista neste artigo, perderá automaticamente sua eficácia caso o portador dela seja detido ou abordado em estado de embriaguez ou sob efeito de substâncias químicas ou alucinógenas."},{"chave":"art-11","sequencia":12,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 11.","conteudo":"Fica instituída a cobrança de taxas, nos valores constantes do Anexo desta Lei, pela prestação de serviços relativos:\n\nI – ao registro de arma de fogo;\n\nII – à renovação de registro de arma de fogo;\n\nIII – à expedição de segunda via de registro de arma de fogo;\n\nIV – à expedição de porte federal de arma de fogo;\n\nV – à renovação de porte de arma de fogo;\n\nVI – à expedição de segunda via de porte federal de arma de fogo.\n\n§ 1º Os valores arrecadados destinam-se ao custeio e à manutenção das atividades do Sinarm, da Polícia Federal e do Comando do Exército, no âmbito de suas respectivas responsabilidades.\n\n§ 2º São isentas do pagamento das taxas previstas neste artigo as pessoas e as instituições a que se referem os incisos I a VII e X e o § 5º do art. 6º desta Lei. (Redação dada pela Lei nº 11.706, de 2008)"},{"chave":"art-11-a","sequencia":13,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO III — DO PORTE"],"titulo":"CAPÍTULO III — DO PORTE","rotulo":"Art. 11-A","conteudo":"O Ministério da Justiça disciplinará a forma e as condições do credenciamento de profissionais pela Polícia Federal para comprovação da aptidão psicológica e da capacidade técnica para o manuseio de arma de fogo. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 1º Na comprovação da aptidão psicológica, o valor cobrado pelo psicólogo não poderá exceder ao valor médio dos honorários profissionais para realização de avaliação psicológica constante do item 1.16 da tabela do Conselho Federal de Psicologia. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 2º Na comprovação da capacidade técnica, o valor cobrado pelo instrutor de armamento e tiro não poderá exceder R$ 80,00 (oitenta reais), acrescido do custo da munição. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 3º A cobrança de valores superiores aos previstos nos §§ 1º e 2º deste artigo implicará o descredenciamento do profissional pela Polícia Federal. (Incluído pela Lei nº 11.706, de 2008)"},{"chave":"art-12","sequencia":14,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"Posse irregular de arma de fogo de uso permitido","rotulo":"Art. 12.","conteudo":"Possuir ou manter sob sua guarda arma de fogo, acessório ou munição, de uso permitido, em desacordo com determinação legal ou regulamentar, no interior de sua residência ou dependência desta, ou, ainda no seu local de trabalho, desde que seja o titular ou o responsável legal do estabelecimento ou empresa:\n\nPena – detenção, de 1 (um) a 3 (três) anos, e multa."},{"chave":"art-13","sequencia":15,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"Omissão de cautela","rotulo":"Art. 13.","conteudo":"Deixar de observar as cautelas necessárias para impedir que menor de 18 (dezoito) anos ou pessoa portadora de deficiência mental se apodere de arma de fogo que esteja sob sua posse ou que seja de sua propriedade:\n\nPena – detenção, de 1 (um) a 2 (dois) anos, e multa.\n\nParágrafo único. Nas mesmas penas incorrem o proprietário ou diretor responsável de empresa de segurança e transporte de valores que deixarem de registrar ocorrência policial e de comunicar à Polícia Federal perda, furto, roubo ou outras formas de extravio de arma de fogo, acessório ou munição que estejam sob sua guarda, nas primeiras 24 (vinte quatro) horas depois de ocorrido o fato."},{"chave":"art-14","sequencia":16,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"Porte ilegal de arma de fogo de uso permitido","rotulo":"Art. 14.","conteudo":"Portar, deter, adquirir, fornecer, receber, ter em depósito, transportar, ceder, ainda que gratuitamente, emprestar, remeter, empregar, manter sob guarda ou ocultar arma de fogo, acessório ou munição, de uso permitido, sem autorização e em desacordo com determinação legal ou regulamentar:\n\nPena – reclusão, de 2 (dois) a 4 (quatro) anos, e multa.\n\nParágrafo único. O crime previsto neste artigo é inafiançável, salvo quando a arma de fogo estiver registrada em nome do agente. (Vide Adin 3.112-1)"},{"chave":"art-15","sequencia":17,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"Disparo de arma de fogo","rotulo":"Art. 15.","conteudo":"Disparar arma de fogo ou acionar munição em lugar habitado ou em suas adjacências, em via pública ou em direção a ela, desde que essa conduta não tenha como finalidade a prática de outro crime:\n\nPena – reclusão, de 2 (dois) a 4 (quatro) anos, e multa.\n\nParágrafo único. O crime previsto neste artigo é inafiançável. (Vide Adin 3.112-1)"},{"chave":"art-16","sequencia":18,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"Posse ou porte ilegal de arma de fogo de uso restrito","rotulo":"Art. 16.","conteudo":"Possuir, deter, portar, adquirir, fornecer, receber, ter em depósito, transportar, ceder, ainda que gratuitamente, emprestar, remeter, empregar, manter sob sua guarda ou ocultar arma de fogo, acessório ou munição de uso restrito, sem autorização e em desacordo com determinação legal ou regulamentar: (Redação dada pela Lei nº 13.964, de 2019)\n\nPena – reclusão, de 3 (três) a 6 (seis) anos, e multa.\n\n§ 1º Nas mesmas penas incorre quem: (Redação dada pela Lei nº 13.964, de 2019)\n\nI – suprimir ou alterar marca, numeração ou qualquer sinal de identificação de arma de fogo ou artefato;\n\nII – modificar as características de arma de fogo, de forma a torná-la equivalente a arma de fogo de uso proibido ou restrito ou para fins de dificultar ou de qualquer modo induzir a erro autoridade policial, perito ou juiz;\n\nIII – possuir, detiver, fabricar ou empregar artefato explosivo ou incendiário, sem autorização ou em desacordo com determinação legal ou regulamentar;\n\nIV – portar, possuir, adquirir, transportar ou fornecer arma de fogo com numeração, marca ou qualquer outro sinal de identificação raspado, suprimido ou adulterado;\n\nV – vender, entregar ou fornecer, ainda que gratuitamente, arma de fogo, acessório, munição ou explosivo a criança ou adolescente; e\n\nVI – produzir, recarregar ou reciclar, sem autorização legal, ou adulterar, de qualquer forma, munição ou explosivo.\n\n§ 2º Se as condutas descritas no caput e no § 1º deste artigo envolverem arma de fogo de uso proibido, a pena é de reclusão, de 4 (quatro) a 12 (doze) anos. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-17","sequencia":19,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"Comércio ilegal de arma de fogo","rotulo":"Art. 17.","conteudo":"Adquirir, alugar, receber, transportar, conduzir, ocultar, ter em depósito, desmontar, montar, remontar, adulterar, vender, expor à venda, ou de qualquer forma utilizar, em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, arma de fogo, acessório ou munição, sem autorização ou em desacordo com determinação legal ou regulamentar:\n\nPena - reclusão, de 6 (seis) a 12 (doze) anos, e multa. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 1º Equipara-se à atividade comercial ou industrial, para efeito deste artigo, qualquer forma de prestação de serviços, fabricação ou comércio irregular ou clandestino, inclusive o exercido em residência. (Redação dada pela Lei nº 13.964, de 2019)\n\n§ 2º Incorre na mesma pena quem vende ou entrega arma de fogo, acessório ou munição, sem autorização ou em desacordo com a determinação legal ou regulamentar, a agente policial disfarçado, quando presentes elementos probatórios razoáveis de conduta criminal preexistente. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-18","sequencia":20,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"Tráfico internacional de arma de fogo","rotulo":"Art. 18.","conteudo":"Importar, exportar, favorecer a entrada ou saída do território nacional, a qualquer título, de arma de fogo, acessório ou munição, sem autorização da autoridade competente:\n\nPena - reclusão, de 8 (oito) a 16 (dezesseis) anos, e multa. (Redação dada pela Lei nº 13.964, de 2019)\n\nParágrafo único. Incorre na mesma pena quem vende ou entrega arma de fogo, acessório ou munição, em operação de importação, sem autorização da autoridade competente, a agente policial disfarçado, quando presentes elementos probatórios razoáveis de conduta criminal preexistente. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-19","sequencia":21,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO IV — DOS CRIMES E DAS PENAS","rotulo":"Art. 19.","conteudo":"Nos crimes previstos nos arts. 17 e 18, a pena é aumentada da metade se a arma de fogo, acessório ou munição forem de uso proibido ou restrito."},{"chave":"art-20","sequencia":22,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO IV — DOS CRIMES E DAS PENAS","rotulo":"Art. 20.","conteudo":"Nos crimes previstos nos arts. 14, 15, 16, 17 e 18, a pena é aumentada da metade se: (Redação dada pela Lei nº 13.964, de 2019)\n\nI - forem praticados por integrante dos órgãos e empresas referidas nos arts. 6º, 7º e 8º desta Lei; ou (Incluído pela Lei nº 13.964, de 2019)\n\nII - o agente for reincidente específico em crimes dessa natureza. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-21","sequencia":23,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO IV — DOS CRIMES E DAS PENAS","rotulo":"Art. 21.","conteudo":"Os crimes previstos nos arts. 16, 17 e 18 são insuscetíveis de liberdade provisória. (Vide Adin 3.112-1)"},{"chave":"art-21-a","sequencia":24,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO IV — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO IV — DOS CRIMES E DAS PENAS","rotulo":"Art. 21-A","conteudo":"Nos crimes previstos nos arts. 12, 14 e 16 desta Lei, a pena é aumentada de 2/3 (dois terços) se o crime for praticado em concurso com crime previsto na Lei nº 11.343, de 23 de agosto de 2006, estiver diretamente ligado ao comércio ilícito de entorpecentes ou o artefato tiver sido utilizado para assegurar o sucesso da mercancia. (Incluído pela Lei nº 15.358, de 2026)"},{"chave":"art-22","sequencia":25,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 22.","conteudo":"O Ministério da Justiça poderá celebrar convênios com os Estados e o Distrito Federal para o cumprimento do disposto nesta Lei."},{"chave":"art-23","sequencia":26,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 23.","conteudo":"A classificação legal, técnica e geral bem como a definição das armas de fogo e demais produtos controlados, de usos proibidos, restritos, permitidos ou obsoletos e de valor histórico serão disciplinadas em ato do chefe do Poder Executivo Federal, mediante proposta do Comando do Exército. (Redação dada pela Lei nº 11.706, de 2008)\n\n§ 1º Todas as munições comercializadas no País deverão estar acondicionadas em embalagens com sistema de código de barras, gravado na caixa, visando possibilitar a identificação do fabricante e do adquirente, entre outras informações definidas pelo regulamento desta Lei.\n\n§ 2º Para os órgãos referidos no art. 6º, somente serão expedidas autorizações de compra de munição com identificação do lote e do adquirente no culote dos projéteis, na forma do regulamento desta Lei.\n\n§ 3º As armas de fogo fabricadas a partir de 1 (um) ano da data de publicação desta Lei conterão dispositivo intrínseco de segurança e de identificação, gravado no corpo da arma, definido pelo regulamento desta Lei, exclusive para os órgãos previstos no art. 6º.\n\n§ 4º As instituições de ensino policial, as guardas municipais referidas no inciso III do caput do art. 6º e no seu § 7º e as escolas de formação de profissionais de segurança privada poderão adquirir insumos e máquinas de recarga de munição para o fim exclusivo de suprimento de suas atividades, mediante autorização concedida nos termos do regulamento. (Redação dada pela Lei nº 14.967, de 2024)"},{"chave":"art-24","sequencia":27,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 24.","conteudo":"Excetuadas as atribuições a que se refere o art. 2º desta Lei, compete ao Comando do Exército autorizar e fiscalizar a produção, exportação, importação, desembaraço alfandegário e o comércio de armas de fogo e demais produtos controlados, inclusive o registro e o porte de trânsito de arma de fogo de colecionadores, atiradores e caçadores."},{"chave":"art-25","sequencia":28,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 25.","conteudo":"As armas de fogo apreendidas, após a elaboração do laudo pericial e sua juntada aos autos, quando não mais interessarem à persecução penal serão encaminhadas pelo juiz competente ao Comando do Exército, no prazo de até 48 (quarenta e oito) horas, para destruição ou doação aos órgãos de segurança pública ou às Forças Armadas, na forma do regulamento desta Lei. (Redação dada pela Lei nº 13.886, de 2019)\n\n§ 1º As armas de fogo encaminhadas ao Comando do Exército que receberem parecer favorável à doação, obedecidos o padrão e a dotação de cada Força Armada ou órgão de segurança pública, atendidos os critérios de prioridade estabelecidos pelo Ministério da Justiça e ouvido o Comando do Exército, serão arroladas em relatório reservado trimestral a ser encaminhado àquelas instituições, abrindo-se-lhes prazo para manifestação de interesse. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 1º-A. As armas de fogo e munições apreendidas em decorrência do tráfico de drogas de abuso, ou de qualquer forma utilizadas em atividades ilícitas de produção ou comercialização de drogas abusivas, ou, ainda, que tenham sido adquiridas com recursos provenientes do tráfico de drogas de abuso, perdidas em favor da União e encaminhadas para o Comando do Exército, devem ser, após perícia ou vistoria que atestem seu bom estado, destinadas com prioridade para os órgãos de segurança pública e do sistema penitenciário da unidade da federação responsável pela apreensão. (Incluído pela Lei nº 13.886, de 2019)\n\n§ 2º O Comando do Exército encaminhará a relação das armas a serem doadas ao juiz competente, que determinará o seu perdimento em favor da instituição beneficiada. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 3º O transporte das armas de fogo doadas será de responsabilidade da instituição beneficiada, que procederá ao seu cadastramento no Sinarm ou no Sigma. (Incluído pela Lei nº 11.706, de 2008)\n\n§ 4º (VETADO) (Incluído pela Lei nº 11.706, de 2008)\n\n§ 5º O Poder Judiciário instituirá instrumentos para o encaminhamento ao Sinarm ou ao Sigma, conforme se trate de arma de uso permitido ou de uso restrito, semestralmente, da relação de armas acauteladas em juízo, mencionando suas características e o local onde se encontram. (Incluído pela Lei nº 11.706, de 2008)"},{"chave":"art-26","sequencia":29,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 26.","conteudo":"São vedadas a fabricação, a venda, a comercialização e a importação de brinquedos, réplicas e simulacros de armas de fogo, que com estas se possam confundir.\n\nParágrafo único. Excetuam-se da proibição as réplicas e os simulacros destinados à instrução, ao adestramento, ou à coleção de usuário autorizado, nas condições fixadas pelo Comando do Exército."},{"chave":"art-27","sequencia":30,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 27.","conteudo":"Caberá ao Comando do Exército autorizar, excepcionalmente, a aquisição de armas de fogo de uso restrito. (Vide ADI 6139)\n\nParágrafo único. O disposto neste artigo não se aplica às aquisições dos Comandos Militares."},{"chave":"art-28","sequencia":31,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 28.","conteudo":"É vedado ao menor de 25 (vinte e cinco) anos adquirir arma de fogo, ressalvados os integrantes das entidades constantes dos incisos I, II, III, V, VI, VII e X do caput do art. 6º desta Lei. (Redação dada pela Lei nº 11.706, de 2008)"},{"chave":"art-29","sequencia":32,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 29.","conteudo":"As autorizações de porte de armas de fogo já concedidas expirar-se-ão 90 (noventa) dias após a publicação desta Lei. (Vide Lei nº 10.884, de 2004)\n\nParágrafo único. O detentor de autorização com prazo de validade superior a 90 (noventa) dias poderá renová-la, perante a Polícia Federal, nas condições dos arts. 4º, 6º e 10 desta Lei, no prazo de 90 (noventa) dias após sua publicação, sem ônus para o requerente."},{"chave":"art-30","sequencia":33,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 30.","conteudo":"Os possuidores e proprietários de arma de fogo de uso permitido ainda não registrada deverão solicitar seu registro até o dia 31 de dezembro de 2008, mediante apresentação de documento de identificação pessoal e comprovante de residência fixa, acompanhados de nota fiscal de compra ou comprovação da origem lícita da posse, pelos meios de prova admitidos em direito, ou declaração firmada na qual constem as características da arma e a sua condição de proprietário, ficando este dispensado do pagamento de taxas e do cumprimento das demais exigências constantes dos incisos I a III do caput do art. 4º desta Lei. (Redação dada pela Lei nº 11.706, de 2008) (Prorrogação de prazo)\n\nParágrafo único. Para fins do cumprimento do disposto no caput deste artigo, o proprietário de arma de fogo poderá obter, no Departamento de Polícia Federal, certificado de registro provisório, expedido na forma do § 4º do art. 5º desta Lei. (Incluído pela Lei nº 11.706, de 2008)"},{"chave":"art-31","sequencia":34,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 31.","conteudo":"Os possuidores e proprietários de armas de fogo adquiridas regularmente poderão, a qualquer tempo, entregá-las à Polícia Federal, mediante recibo e indenização, nos termos do regulamento desta Lei."},{"chave":"art-32","sequencia":35,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 32.","conteudo":"Os possuidores e proprietários de arma de fogo poderão entregá-la, espontaneamente, mediante recibo, e, presumindo-se de boa-fé, serão indenizados, na forma do regulamento, ficando extinta a punibilidade de eventual posse irregular da referida arma. (Redação dada pela Lei nº 11.706, de 2008)\n\nParágrafo único. (Revogado pela Lei nº 11.706, de 2008)"},{"chave":"art-33","sequencia":36,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 33.","conteudo":"Será aplicada multa de R$ 100.000,00 (cem mil reais) a R$ 300.000,00 (trezentos mil reais), conforme especificar o regulamento desta Lei:\n\nI – à empresa de transporte aéreo, rodoviário, ferroviário, marítimo, fluvial ou lacustre que deliberadamente, por qualquer meio, faça, promova, facilite ou permita o transporte de arma ou munição sem a devida autorização ou com inobservância das normas de segurança;\n\nII – à empresa de produção ou comércio de armamentos que realize publicidade para venda, estimulando o uso indiscriminado de armas de fogo, exceto nas publicações especializadas."},{"chave":"art-34","sequencia":37,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 34.","conteudo":"Os promotores de eventos em locais fechados, com aglomeração superior a 1000 (um mil) pessoas, adotarão, sob pena de responsabilidade, as providências necessárias para evitar o ingresso de pessoas armadas, ressalvados os eventos garantidos pelo inciso VI do art. 5º da Constituição Federal.\n\nParágrafo único. As empresas responsáveis pela prestação dos serviços de transporte internacional e interestadual de passageiros adotarão as providências necessárias para evitar o embarque de passageiros armados."},{"chave":"art-34-a","sequencia":38,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO V — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO V — DISPOSIÇÕES GERAIS","rotulo":"Art. 34-A","conteudo":"Os dados relacionados à coleta de registros balísticos serão armazenados no Banco Nacional de Perfis Balísticos. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 1º O Banco Nacional de Perfis Balísticos tem como objetivo cadastrar armas de fogo e armazenar características de classe e individualizadoras de projéteis e de estojos de munição deflagrados por arma de fogo. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 2º O Banco Nacional de Perfis Balísticos será constituído pelos registros de elementos de munição deflagrados por armas de fogo relacionados a crimes, para subsidiar ações destinadas às apurações criminais federais, estaduais e distritais. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 3º O Banco Nacional de Perfis Balísticos será gerido pela unidade oficial de perícia criminal. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 4º Os dados constantes do Banco Nacional de Perfis Balísticos terão caráter sigiloso, e aquele que permitir ou promover sua utilização para fins diversos dos previstos nesta Lei ou em decisão judicial responderá civil, penal e administrativamente. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 5º É vedada a comercialização, total ou parcial, da base de dados do Banco Nacional de Perfis Balísticos. (Incluído pela Lei nº 13.964, de 2019)\n\n§ 6º A formação, a gestão e o acesso ao Banco Nacional de Perfis Balísticos serão regulamentados em ato do Poder Executivo federal. (Incluído pela Lei nº 13.964, de 2019)"},{"chave":"art-35","sequencia":39,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO VI — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VI — DISPOSIÇÕES FINAIS","rotulo":"Art. 35.","conteudo":"É proibida a comercialização de arma de fogo e munição em todo o território nacional, salvo para as entidades previstas no art. 6º desta Lei.\n\n§ 1º Este dispositivo, para entrar em vigor, dependerá de aprovação mediante referendo popular, a ser realizado em outubro de 2005.\n\n§ 2º Em caso de aprovação do referendo popular, o disposto neste artigo entrará em vigor na data de publicação de seu resultado pelo Tribunal Superior Eleitoral."},{"chave":"art-36","sequencia":40,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO VI — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VI — DISPOSIÇÕES FINAIS","rotulo":"Art. 36.","conteudo":"É revogada a Lei nº 9.437, de 20 de fevereiro de 1997."},{"chave":"art-37","sequencia":41,"caminho":["ESTATUTO DO DESARMAMENTO","CAPÍTULO VI — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VI — DISPOSIÇÕES FINAIS","rotulo":"Art. 37.","conteudo":"Esta Lei entra em vigor na data de sua publicação."},{"chave":"anexo-tabela-taxas","sequencia":42,"caminho":["ESTATUTO DO DESARMAMENTO","ANEXO — TABELA DE TAXAS"],"titulo":"ANEXO — TABELA DE TAXAS","rotulo":"Anexo","conteudo":"Redação dada pela Lei nº 11.706, de 2008.\n\nTABELA DE TAXAS\n\nATO ADMINISTRATIVO — R$\nI - Registro de arma de fogo:\n- até 31 de dezembro de 2008 — Gratuito (art. 30)\n- a partir de 1º de janeiro de 2009 — 60,00\nII - Renovação do certificado de registro de arma de fogo: — Gratuito\n- até 31 de dezembro de 2008 — (art. 5º, § 3º)\n- a partir de 1º de janeiro de 2009 — 60,00\nIII - Registro de arma de fogo para empresa de segurança privada e de transporte de valores — 60,00\nIV - Renovação do certificado de registro de arma de fogo para empresa de segurança privada e de transporte de valores:\n- até 30 de junho de 2008 — 30,00\n- de 1º de julho de 2008 a 31 de outubro de 2008 — 45,00\n- a partir de 1º de novembro de 2008 — 60,00\nV - Expedição de porte de arma de fogo — 1.000,00\nVI - Renovação de porte de arma de fogo — 1.000,00\nVII - Expedição de segunda via de certificado de registro de arma de fogo — 60,00\nVIII - Expedição de segunda via de porte de arma de fogo — 60,00"}]$dados$::jsonb)
    as item(chave text, sequencia integer, caminho text[], titulo text, rotulo text, conteudo text);

